import { useState } from 'preact/hooks';

import { useDispatch } from 'react-redux';

import StateIndicator, { StateIndicatorPropsType } from '../../../../shared/StateIndicator';
import { createUser } from '../../../user/slice';
import Button from '../../../../shared/Button';

import ConfirmAge from './ConfirmAge';

import styles from './styles.module.scss';
import { FunctionComponent } from 'preact';

// -----------------------------------------------------------------------------

interface FormProps {
  onSubmit: (name: string, isAgeConfirmed: boolean) => unknown,
}

const Form: FunctionComponent<FormProps> = ({ onSubmit }: FormProps) => {
  const [isAgeConfirmed, setAgeConfirmed] = useState(false);
  const [name, setName] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(name, isAgeConfirmed);
  };

  const handleChange = (evt) => {
    setName(evt.target.value);
  };

  const isValid = name.length && isAgeConfirmed;

  return (
    <form onSubmit={handleSubmit}>
      <div className={styles.textInput}>
        <label htmlFor="name">Enter your name</label>
        <input
          required
          type="text"
          name="name"
          value={name}
          onChange={handleChange}
        />
      </div>

      <ConfirmAge checked={isAgeConfirmed} onChange={setAgeConfirmed} />

      <div className={styles.buttonsFooter}>
        <Button size="large" type="submit" variant="primary" disabled={!isValid}>
          Continue
        </Button>
      </div>
    </form>
  );
};

const STATES = {
  form: 'form',
  loading: 'loading',
  success: 'success',
  error: 'error',
};

const wait = (timeout) =>
  new Promise((resolve) => setTimeout(resolve, timeout));

interface SignUpFormProps {
  onFinished: () => unknown,
}

// All the functionality here
export const SignUpForm: FunctionComponent<SignUpFormProps> = ({ onFinished }: SignUpFormProps) => {
  const dispatch = useDispatch();
  const [state, setState] = useState<{type: string, message?: string}>({
    type: STATES.form,
    message: null,
  });

  const handleSubmit = async (name, isAgeConfirmed) => {
    setState({ type: STATES.loading });
    try {
      // eslint-disable-next-line @typescript-eslint/await-thenable
      await dispatch(createUser({ name, isAgeConfirmed }));
      setState({ type: STATES.success });
      await wait(1000);
      onFinished();
    } catch (e) {
      console.error('handleSubmit', e);
      const message = 'There was an error. Try again later or contact support.';
      setState({ type: STATES.error, message });
      await wait(2000);
      setState({ type: STATES.form });
    }
  };

  return state.type === STATES.form ? (
    <Form onSubmit={handleSubmit} />
  ) : (
    <StateIndicator type={state.type as StateIndicatorPropsType} message={state.message} />
  );
};

export default SignUpForm;
